<?php
/* Caminho: admin/comercial.php */
declare(strict_types=1);
require dirname(__DIR__).'/includes/bootstrap.php';arc_require_admin();$pdo=arc_db();arc_ensure_user_schema($pdo);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  arc_verify_csrf();$action=(string)($_POST['action']??'');
  if($action==='plan_save'){
   $name=trim((string)($_POST['name']??''));$price=filter_var($_POST['price_cents']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>100,'max_range'=>100000000]]);
   if($name===''||mb_strlen($name)>80||$price===false)throw new RuntimeException('Informe nome e valor em centavos válidos.');
   $values=[$name,$price];foreach(['networks_limit','agents_limit','seats_limit'] as $k){$v=filter_var($_POST[$k]??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>0,'max_range'=>1000000]]);if($v===false)throw new RuntimeException('Limites inválidos.');$values[]=$v;}$values[]=isset($_POST['enabled'])?1:0;$id=(int)($_POST['plan_id']??0);
   if($id)$pdo->prepare('UPDATE '.arc_table('billing_plans').' SET name=?,price_cents=?,networks_limit=?,agents_limit=?,seats_limit=?,enabled=? WHERE id=?')->execute([...$values,$id]);else $pdo->prepare('INSERT INTO '.arc_table('billing_plans').' (name,price_cents,networks_limit,agents_limit,seats_limit,enabled) VALUES (?,?,?,?,?,?)')->execute($values);
  }elseif($action==='gateway_save'){
   $url=rtrim(trim((string)($_POST['public_url']??'')),'/');if(!preg_match('~^https://[a-z0-9.-]+(?::443)?(?:/[a-zA-Z0-9_/-]*)?$~D',$url))throw new RuntimeException('Informe a URL HTTPS pública correta.');
   $pdo->beginTransaction();
   arc_platform_save_setting($pdo,'platform_billing_public_url',$url);
   foreach(['mercadopago','asaas'] as $provider){
    $mode=(string)($_POST[$provider.'_mode']??'sandbox');if(!in_array($mode,['sandbox','production'],true))throw new RuntimeException('Ambiente inválido.');
    arc_platform_save_setting($pdo,'platform_billing_'.$provider.'_mode',$mode);
    foreach(['key','hook'] as $field){$v=trim((string)($_POST[$provider.'_'.$field]??''));if(strlen($v)>2048||($v!==''&&preg_match('/[\r\n]/',$v)))throw new RuntimeException('Credencial inválida.');if($v!=='')arc_platform_save_setting($pdo,'platform_billing_'.$provider.'_'.$field,arc_platform_encrypt($v));}
    $enabled=isset($_POST[$provider.'_enabled']);if($enabled&&(arc_platform_decrypt(arc_billing_setting($pdo,$provider.'_key'))===''||strlen(arc_platform_decrypt(arc_billing_setting($pdo,$provider.'_hook')))<16))throw new RuntimeException('Configure chave e segredo webhook (mínimo 16 caracteres) antes de ativar '.$provider.'.');
    arc_platform_save_setting($pdo,'platform_billing_'.$provider.'_enabled',$enabled?'1':'0');
   }
   $pix=trim((string)($_POST['pix_key']??''));if(mb_strlen($pix)>254)throw new RuntimeException('Chave Pix inválida.');if(isset($_POST['pix_enabled'])&&$pix==='')throw new RuntimeException('Informe a chave Pix.');
   $pixName=arc_pix_name((string)($_POST['pix_name']??''),25);$pixCity=arc_pix_name((string)($_POST['pix_city']??''),15);
   if(isset($_POST['pix_enabled']))arc_billing_pix_payload($pix,$pixName,$pixCity,100,'TESTE');
   arc_platform_save_setting($pdo,'platform_billing_pix_name',$pixName);arc_platform_save_setting($pdo,'platform_billing_pix_city',$pixCity);
   arc_platform_save_setting($pdo,'platform_billing_pix_key',$pix);arc_platform_save_setting($pdo,'platform_billing_pix_instructions',mb_substr(trim((string)($_POST['pix_instructions']??'')),0,1000));arc_platform_save_setting($pdo,'platform_billing_pix_enabled',isset($_POST['pix_enabled'])?'1':'0');
   if(isset($_POST['activate_trials'])&&arc_billing_setting($pdo,'launch_at')==='')arc_platform_save_setting($pdo,'platform_billing_launch_at',date('Y-m-d H:i:s'));
   foreach(['low','normal','high','urgent'] as $priority){$hours=filter_var($_POST['sla_'.$priority]??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>720]]);if($hours===false)throw new RuntimeException('SLA inválido.');arc_platform_save_setting($pdo,'platform_support_sla_'.$priority,(string)$hours);}
   $pdo->commit();
  }elseif($action==='pix_approve'){
   $id=(int)($_POST['invoice_id']??0);$q=$pdo->prepare("SELECT * FROM ".arc_table('billing_invoices')." WHERE id=? AND provider='pix' AND status='review'");$q->execute([$id]);$i=$q->fetch();if(!$i||!isset($_POST['confirmed_receipt']))throw new RuntimeException('Confirme o recebimento na sua conta bancária.');
   arc_billing_apply($pdo,$id,'paid','manual-'.$id,'pix',(int)arc_admin_id());
  }elseif($action==='subscription_manage'){
   $account=(int)($_POST['account_id']??0);$operation=(string)($_POST['operation']??'');
   if($operation==='pause')$pdo->prepare("UPDATE ".arc_table('billing_subscriptions')." SET status='paused' WHERE account_id=?")->execute([$account]);
   elseif($operation==='resume')$pdo->prepare("UPDATE ".arc_table('billing_subscriptions')." SET status='active' WHERE account_id=? AND period_end>NOW() AND status='paused'")->execute([$account]);
   elseif($operation==='cancel')$pdo->prepare('UPDATE '.arc_table('billing_subscriptions').' SET cancel_at_period_end=1 WHERE account_id=?')->execute([$account]);
   else throw new RuntimeException('Operação de assinatura inválida.');
   arc_audit($pdo,'subscription_'.$operation,'Conta #'.$account);
  }elseif($action==='reconcile'){
   $q=$pdo->prepare('SELECT * FROM '.arc_table('billing_invoices').' WHERE id=?');$q->execute([(int)($_POST['invoice_id']??0)]);$i=$q->fetch();if(!$i||!in_array($i['provider'],['mercadopago','asaas'],true))throw new RuntimeException('Cobrança inválida.');
   if($i['provider']==='mercadopago'){$r=arc_billing_http($pdo,'mercadopago','GET','/v1/payments/search?external_reference='.$i['reference']);$rows=$r['results']??[];}else{$r=arc_billing_http($pdo,'asaas','GET','/payments?externalReference='.$i['reference']);$rows=$r['data']??[];}
   if(!$rows)throw new RuntimeException('Gateway não retornou pagamento para esta referência. Nenhum plano foi liberado.');
   foreach($rows as $pay){$state=arc_billing_payment_state($i,$pay);arc_billing_apply($pdo,(int)$i['id'],$state,(string)$pay['id'].':'.$state,$i['provider'],(int)arc_admin_id());}
  }else throw new RuntimeException('Ação inválida.');
  arc_audit($pdo,'commercial_admin','Operação '.$action.' por administrador #'.(int)arc_admin_id());$_SESSION['arc_flash']='Operação registrada.';header('Location: '.arc_workspace_base_url().'admin/comercial.php',true,303);exit;
 }catch(RuntimeException $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'Serviço indisponível. Verifique os registros do servidor.':$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Comercial: '.$e->getMessage());$error='Não foi possível concluir. Confira os registros do servidor.';}
}
$plans=$pdo->query('SELECT * FROM '.arc_table('billing_plans').' ORDER BY price_cents,id')->fetchAll();$plans[]=['id'=>0,'name'=>'','price_cents'=>5990,'networks_limit'=>3,'agents_limit'=>15,'seats_limit'=>2,'enabled'=>1];
$invoices=$pdo->query('SELECT i.*,u.display_name FROM '.arc_table('billing_invoices').' i JOIN '.arc_table('user_accounts').' u ON u.id=i.account_id ORDER BY i.id DESC LIMIT 100')->fetchAll();
$subscriptions=$pdo->query('SELECT s.*,u.display_name,p.name FROM '.arc_table('billing_subscriptions').' s JOIN '.arc_table('user_accounts').' u ON u.id=s.account_id JOIN '.arc_table('billing_plans').' p ON p.id=s.plan_id ORDER BY s.updated_at DESC LIMIT 100')->fetchAll();
$subscriptionCount=(int)$pdo->query('SELECT COUNT(*) FROM '.arc_table('billing_subscriptions'))->fetchColumn();
$revenue=(int)$pdo->query("SELECT COALESCE(SUM(amount_cents),0) FROM ".arc_table('billing_invoices')." WHERE status='paid' AND paid_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)")->fetchColumn();
$ARCPageTitle='Gestão comercial';$ARCActiveNav='commercial';require dirname(__DIR__).'/includes/header.php';require dirname(__DIR__).'/includes/sidebar.php';
?>
<main class="app-main"><div class="page-content arc-service">
<header class="arc-service-heading"><div><h1>Gestão comercial</h1><p>Planos, gateways, assinaturas e conciliação em um só lugar.</p></div></header>
<?php if($error):?><p class="arc-service-error" role="alert"><?=arc_h($error)?></p><?php endif;?>
<div class="arc-service-metrics"><article><small>Recebido nos últimos 30 dias</small><strong><?=arc_money($revenue)?></strong></article><article><small>Assinaturas registradas</small><strong><?=$subscriptionCount?></strong></article><article><small>Pix aguardando conferência (últimas 100)</small><strong><?=count(array_filter($invoices,fn($i)=>$i['provider']==='pix'&&$i['status']==='review'))?></strong></article></div>
<nav class="arc-service-tabs" aria-label="Gestão comercial"><a href="#commercial-plans">Planos</a><a href="#commercial-gateways">Pagamentos</a><a href="#commercial-invoices">Cobranças</a><a href="#commercial-subscriptions">Assinaturas</a></nav>
<section id="commercial-plans" class="arc-service-card"><h2>Catálogo de planos</h2><span class="arc-page-help"><button type="button" class="arc-icon-action" data-open-dialog="page-help-1" aria-label="Saiba mais sobre esta área" title="Saiba mais"><i class="fa fa-info" aria-hidden="true"></i></button></span><dialog id="page-help-1" class="arc-service-dialog"><header class="arc-service-heading"><h2>Saiba mais</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><p>Valores sugeridos são editáveis. Limite zero significa ilimitado. Alterações não modificam cobranças já emitidas.</p></dialog><div class="arc-service-plans arc-catalog"><?php foreach($plans as $p):?><article class="arc-service-card arc-plan-card"><h2><?=$p['id']?arc_h($p['name']):'Novo plano'?></h2><p class="arc-plan-price"><?=arc_money((int)$p['price_cents'])?></p><button type="button" class="arc-icon-action arc-plan-open" data-open-dialog="edit-plan-<?=(int)$p['id']?>" aria-label="<?=$p['id']?'Editar plano':'Criar plano'?>" title="Configurar plano"><i class="fa <?=$p['id']?'fa-pencil':'fa-plus'?>" aria-hidden="true"></i></button><dialog class="arc-service-dialog" id="edit-plan-<?=(int)$p['id']?>"><header class="arc-service-heading"><h2>Configurar plano</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><form method="post" class="arc-service-form arc-service-card"><h3><?=$p['id']?arc_h($p['name']):'Novo plano'?></h3><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="action" value="plan_save"><input type="hidden" name="plan_id" value="<?=(int)$p['id']?>"><?php foreach(['name'=>'Nome','price_cents'=>'Preço mensal em centavos','networks_limit'=>'Redes','agents_limit'=>'Agentes','seats_limit'=>'Técnicos adicionais'] as $k=>$label):?><label><?=$label?><input name="<?=$k?>" value="<?=arc_h($p[$k])?>" type="<?=$k==='name'?'text':'number'?>" <?=$k==='name'?'maxlength="80"':'min="0" max="100000000"'?> required></label><?php endforeach;?><label class="arc-service-check"><input type="checkbox" name="enabled" <?=$p['enabled']?'checked':''?>> Disponível no catálogo</label><button class="button primary" aria-label="Salvar plano" title="Salvar plano"><i class="fa fa-check" aria-hidden="true"></i><span class="arc-action-label">Salvar plano</span></button></form></dialog></article><?php endforeach;?></div></section>
<section id="commercial-gateways" class="arc-service-card"><h2>Gateways e operação</h2><span class="arc-page-help"><button type="button" class="arc-icon-action" data-open-dialog="page-help-2" aria-label="Saiba mais sobre esta área" title="Saiba mais"><i class="fa fa-info" aria-hidden="true"></i></button></span><dialog id="page-help-2" class="arc-service-dialog"><header class="arc-service-heading"><h2>Saiba mais</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><p>As credenciais ficam criptografadas. Campos vazios preservam o segredo existente. Configure os webhooks nos painéis dos gateways antes de ativar vendas.</p></dialog><button type="button" class="arc-icon-action" data-open-dialog="billing-gateway-settings" aria-label="Configurar pagamentos e prazos" title="Configurar pagamentos"><i class="fa fa-cog" aria-hidden="true"></i></button><dialog class="arc-service-dialog" id="billing-gateway-settings"><header class="arc-service-heading"><h2>Pagamentos e prazos</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><form method="post" class="arc-service-form"><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="action" value="gateway_save"><label>URL pública HTTPS da plataforma<input name="public_url" type="url" placeholder="https://app.seudominio.com.br" value="<?=arc_h(arc_billing_setting($pdo,'public_url'))?>" required></label><div class="arc-service-plans"><?php foreach(['mercadopago'=>'Mercado Pago','asaas'=>'Asaas'] as $k=>$label):?><fieldset class="arc-service-card"><legend><?=$label?></legend><label class="arc-service-check"><input name="<?=$k?>_enabled" type="checkbox" <?=arc_billing_setting($pdo,$k.'_enabled')==='1'?'checked':''?>> Ativar checkout</label><label>Ambiente<select name="<?=$k?>_mode"><option value="sandbox" <?=arc_billing_setting($pdo,$k.'_mode','sandbox')==='sandbox'?'selected':''?>>Teste</option><option value="production" <?=arc_billing_setting($pdo,$k.'_mode')==='production'?'selected':''?>>Produção</option></select></label><label>Access token / API key<input name="<?=$k?>_key" type="password" autocomplete="new-password" placeholder="<?=arc_billing_setting($pdo,$k.'_key')!==''?'Configurado — deixe vazio para preservar':'Não configurado'?>"></label><label><?=$k==='mercadopago'?'Assinatura secreta do webhook (painel Mercado Pago)':'Token de autenticação do webhook (defina igual no Asaas)'?><input name="<?=$k?>_hook" type="password" autocomplete="new-password" placeholder="<?=arc_billing_setting($pdo,$k.'_hook')!==''?'Configurado':'Não configurado'?>"></label><p>Webhook: <code><?=arc_h(rtrim(arc_billing_setting($pdo,'public_url'),'/').'/api/billing-webhook.php?provider='.$k)?></code></p></fieldset><?php endforeach;?></div><fieldset class="arc-service-card"><legend>Pix manual</legend><label class="arc-service-check"><input type="checkbox" name="pix_enabled" <?=arc_billing_setting($pdo,'pix_enabled')==='1'?'checked':''?>> Ativar Pix com conferência administrativa</label><label>Chave Pix<input name="pix_key" maxlength="254" value="<?=arc_h(arc_billing_setting($pdo,'pix_key'))?>"></label><label>Nome do beneficiário<input name="pix_name" maxlength="25" value="<?=arc_h(arc_billing_setting($pdo,'pix_name','ARCOLL'))?>"></label><label>Cidade do beneficiário<input name="pix_city" maxlength="15" value="<?=arc_h(arc_billing_setting($pdo,'pix_city','BELEM'))?>"></label><label>Orientações<textarea name="pix_instructions" maxlength="1000"><?=arc_h(arc_billing_setting($pdo,'pix_instructions'))?></textarea></label></fieldset><fieldset class="arc-service-card"><legend>Novas contas e SLA</legend><label class="arc-service-check"><input type="checkbox" name="activate_trials" <?=arc_billing_setting($pdo,'launch_at')!==''?'checked disabled':''?>> Ativar avaliação de 14 dias para contas criadas a partir de agora</label><span class="arc-page-help"><button type="button" class="arc-icon-action" data-open-dialog="page-help-3" aria-label="Saiba mais sobre esta área" title="Saiba mais"><i class="fa fa-info" aria-hidden="true"></i></button></span><dialog id="page-help-3" class="arc-service-dialog"><header class="arc-service-heading"><h2>Saiba mais</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><p>Contas anteriores permanecem preservadas. A ativação estabelece uma data de início e não apaga dados.</p></dialog><?php foreach(['low'=>24,'normal'=>8,'high'=>4,'urgent'=>1] as $priority=>$hours):?><label>SLA <?=$priority?> em horas<input type="number" name="sla_<?=$priority?>" min="1" max="720" value="<?=arc_h(arc_platform_setting($pdo,'platform_support_sla_'.$priority,(string)$hours))?>"></label><?php endforeach;?></fieldset><button class="button primary" aria-label="Salvar configurações" title="Salvar configurações"><i class="fa fa-check" aria-hidden="true"></i><span class="arc-action-label">Salvar configurações</span></button></form></dialog></section>
<section id="commercial-invoices" class="arc-service-card"><h2>Conciliação de cobranças</h2><div class="arc-service-list"><?php foreach($invoices as $i):?><article><div><strong>#<?=(int)$i['id']?> · <?=arc_h($i['display_name'])?> · <?=arc_money((int)$i['amount_cents'])?></strong><p><?=arc_h($i['provider'].' · '.$i['status'].' · '.$i['reference'])?></p><?php if($i['receipt_note']):?><p>Referência informada: <?=arc_h($i['receipt_note'])?></p><?php endif;?></div><form method="post" class="arc-service-form"><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="invoice_id" value="<?=(int)$i['id']?>"><?php if($i['provider']==='pix'&&$i['status']==='review'):?><label class="arc-service-check"><input type="checkbox" name="confirmed_receipt" required> Recebimento conferido no banco</label><button class="button" name="action" value="pix_approve" aria-label="Confirmar Pix e liberar plano" title="Confirmar Pix e liberar plano"><i class="fa fa-check" aria-hidden="true"></i><span class="arc-action-label">Confirmar Pix e liberar plano</span></button><?php elseif(in_array($i['provider'],['asaas','mercadopago'],true)):?><button class="button" name="action" value="reconcile" aria-label="Consultar gateway e conciliar" title="Consultar gateway e conciliar"><i class="fa fa-refresh" aria-hidden="true"></i><span class="arc-action-label">Consultar gateway e conciliar</span></button><?php endif;?></form></article><?php endforeach;?><?php if(!$invoices):?><p>Nenhuma cobrança registrada.</p><?php endif;?></div></section>
<section id="commercial-subscriptions" class="arc-service-card"><h2>Assinaturas</h2><div class="arc-service-list"><?php foreach($subscriptions as $s):?><article><div><strong><?=arc_h($s['display_name'].' · '.$s['name'])?></strong><p><?=arc_h($s['status'])?> · até <?=arc_h(arc_when($s['period_end']))?><?=$s['cancel_at_period_end']?' · renovação cancelada':''?></p></div><form method="post" class="arc-service-form"><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="action" value="subscription_manage"><input type="hidden" name="account_id" value="<?=(int)$s['account_id']?>"><label>Ação administrativa<select name="operation"><option value="pause">Pausar novas operações</option><option value="resume">Retomar período pago ainda válido</option><option value="cancel">Cancelar próxima renovação</option></select></label><button class="button" aria-label="Aplicar" title="Aplicar"><i class="fa fa-check" aria-hidden="true"></i><span class="arc-action-label">Aplicar</span></button></form></article><?php endforeach;?><?php if(!$subscriptions):?><p>Nenhuma assinatura registrada.</p><?php endif;?></div></section>
